_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Flat non-decaying lifts collapse under within-team baseline; team-quality confound.", "observed_sample_and_power": "n>150k per lag; 915,570 possessions", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "failed_gate"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-073"}]}, {"id": "FAM:SF-CHT-037", "label": "Study family SF-CHT-037: Sequence-memory lag effects with game-state controls", "score": 0.207, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-037 (0.21)"], "attributes": {"observed_research_question": "Sequence-memory lag effects with game-state controls", "auto_outcome_status": "artifact", "observed_hypothesis": "Naive lag-1 play-type PPP effects survive period/clock/margin controls and within-team baselines.", "observed_result": "Lag-1 real, lag-2 small, lag-3+ ~0: d(1)=+0.024 AUC, d(2)=+0.004. SPOT_UP lag-1 MWU_p=0.0000 with and without controls. DRIVE lag-1 MWU_p=0.0000 but ctrl_p=0.0911. PNR naive p=0.031, controlled 0.136, within-team lift -0 [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "DRIVE and PNR lag-1 effects disappear with game-state controls / within-team baseline.", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-073"}, {"rel": "auto_related_family", "node": "FAM:SF-CHT-029"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.162, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-009 (0.16)"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}], "n_results": 4}

